import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1000000007L;

    static class Line {
        long m, c;
        Line(long m, long c) {
            this.m = m;
            this.c = c;
        }
    }

    static class Meal {
        int a, b;
        Meal(int a, int b) {
            this.a = a;
            this.b = b;
        }
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int M = fs.nextInt();
        long K = fs.nextLong();

        int[] spellA = new int[N];
        int[] spellB = new int[N];
        for (int i = 0; i < N; i++) spellA[i] = fs.nextInt();
        for (int i = 0; i < N; i++) spellB[i] = fs.nextInt();

        int[] mealA = new int[M];
        int[] mealB = new int[M];
        for (int i = 0; i < M; i++) mealA[i] = fs.nextInt();
        for (int i = 0; i < M; i++) mealB[i] = fs.nextInt();

        int Q = fs.nextInt();
        long[] queries = new long[Q];
        for (int i = 0; i < Q; i++) queries[i] = fs.nextLong();

        // Preprocess spells: max-slope spell and upper hull for first spell
        int maxA = 0, maxB = -1;
        Line[] lines = new Line[N];
        for (int i = 0; i < N; i++) {
            int a = spellA[i];
            int b = spellB[i];
            lines[i] = new Line(a, b);
            if (a > maxA || (a == maxA && b > maxB)) {
                maxA = a;
                maxB = b;
            }
        }

        Arrays.sort(lines, (l1, l2) -> {
            if (l1.m != l2.m) return Long.compare(l1.m, l2.m);
            return Long.compare(l2.c, l1.c);
        });

        ArrayList<Line> hull = new ArrayList<>();
        for (Line l : lines) {
            if (!hull.isEmpty() && hull.get(hull.size() - 1).m == l.m) continue;
            while (hull.size() >= 2) {
                Line l1 = hull.get(hull.size() - 2);
                Line l2 = hull.get(hull.size() - 1);
                Line l3 = l;
                long left = (l1.c - l2.c) * (l3.m - l2.m);
                long right = (l2.c - l3.c) * (l2.m - l1.m);
                if (left >= right) {
                    hull.remove(hull.size() - 1);
                } else {
                    break;
                }
            }
            hull.add(l);
        }

        // Preprocess meals: sort by (a-1)/b ascending, b=0 last
        Meal[] meals = new Meal[M];
        for (int i = 0; i < M; i++) {
            meals[i] = new Meal(mealA[i], mealB[i]);
        }

        Arrays.sort(meals, (m1, m2) -> {
            if (m1.b == 0 && m2.b == 0) return 0;
            if (m1.b == 0) return 1;
            if (m2.b == 0) return -1;
            long left = (long) (m1.a - 1) * m2.b;
            long right = (long) (m2.a - 1) * m1.b;
            if (left < right) return -1;
            if (left > right) return 1;
            return 0;
        });

        long mealMul = 1;
        long mealAdd = 0;
        for (Meal meal : meals) {
            long a = meal.a % MOD;
            long b = meal.b % MOD;
            mealMul = mealMul * a % MOD;
            mealAdd = (a * mealAdd + b) % MOD;
        }

        long exp = K - 1;
        StringBuilder sb = new StringBuilder();

        for (int qi = 0; qi < Q; qi++) {
            long x = queries[qi];
            long y0 = queryHull(hull, x);
            long yMod = y0 % MOD;

            if (exp > 0) {
                if (maxA == 1) {
                    yMod = (yMod + (exp % MOD) * (maxB % MOD)) % MOD;
                } else {
                    long A_mod = maxA % MOD;
                    long B_mod = maxB % MOD;
                    long Apow = modPow(A_mod, exp, MOD);
                    long inv = modPow((maxA - 1) % MOD, MOD - 2, MOD);
                    long geo = (Apow - 1 + MOD) % MOD * inv % MOD;
                    yMod = (Apow * yMod + B_mod * geo) % MOD;
                }
            }

            long ans = (mealMul * yMod + mealAdd) % MOD;
            sb.append(ans).append('\n');
        }

        System.out.print(sb);
    }

    static long queryHull(ArrayList<Line> hull, long x) {
        int lo = 0, hi = hull.size() - 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            Line l1 = hull.get(mid);
            Line l2 = hull.get(mid + 1);
            long v1 = l1.m * x + l1.c;
            long v2 = l2.m * x + l2.c;
            if (v1 <= v2) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        Line best = hull.get(lo);
        return best.m * x + best.c;
    }

    static long modPow(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}
